messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/libtests/pngimage.c
Line: 1193
Function: compare_read
Bug type: stack-buffer-overflow
CWE: CWE-121
Explanation: In the 16-bit path of the sBIT handling, the loop uses b = (bpp >> 4) down to 1, but indexes sig_bits[b] and writes to sig_bits[2*b+1] and sig_bits[2*b]. For RGBA16 (comps=4), this reads sig_bits[4] (OOB) and writes sig_bits[9] and sig_bits[8] (OOB) into an 8-byte array. This leads to out-of-bounds read and stack-based buffer overflow when bit_depth == 16 and color_type has multiple components.

Source context:
```c
     1153:                /*NOTREACHED*/
     1154:                memset(sig_bits, 0, sizeof(sig_bits));
     1155:                bpp = 0;
     1156:                break;
     1157:          }
     1158: 
     1159:          {
     1160:             int b;
     1161: 
     1162:             for (b=0; 8*b<bpp; ++b)
     1163:             {
     1164:                /* libpng should catch this; if not there is a security issue
     1165:                 * because an app (like this one) may overflow an array. In fact
     1166:                 * libpng doesn't catch this at present.
     1167:                 */
     1168:                if (sig_bits[b] == 0 || sig_bits[b] > bit_depth/*!palette*/)
     1169:                   display_log(dp, LIBPNG_BUG,
     1170:                      "invalid sBIT[%u]  value %d returned for PNG bit depth %d",
     1171:                      b, sig_bits[b], bit_depth);
     1172:             }
     1173:          }
     1174: 
     1175:          if (bpp < 8 && bpp != bit_depth)
     1176:          {
     1177:             /* sanity check; this is a grayscale PNG; something is wrong in the
     1178:              * code above.
     1179:              */
     1180:             display_log(dp, INTERNAL_ERROR, "invalid bpp %u for bit_depth %u",
     1181:                bpp, bit_depth);
     1182:          }
     1183: 
     1184:          switch (bit_depth)
     1185:          {
     1186:             int b;
     1187: 
     1188:             case 16: /* Two bytes per component, big-endian */
     1189:                for (b = (bpp >> 4); b > 0; --b)
     1190:                {
     1191:                   unsigned int sig = (unsigned int)(0xffff0000 >> sig_bits[b]);
     1192: 
>>>  1193:                   sig_bits[2*b+1] = (png_byte)sig;
     1194:                   sig_bits[2*b+0] = (png_byte)(sig >> 8); /* big-endian */
     1195:                }
     1196:                break;
     1197: 
     1198:             case 8: /* One byte per component */
     1199:                for (b=0; b*8 < bpp; ++b)
     1200:                   sig_bits[b] = (png_byte)(0xff00 >> sig_bits[b]);
     1201:                break;
     1202: 
     1203:             case 1: /* allowed, but dumb */
     1204:                /* Value is 1 */
     1205:                sig_bits[0] = 0xff;
     1206:                break;
     1207: 
     1208:             case 2: /* Replicate 4 times */
     1209:                /* Value is 1 or 2 */
     1210:                b = 0x3 & ((0x3<<2) >> sig_bits[0]);
     1211:                b |= b << 2;
     1212:                b |= b << 4;
     1213:                sig_bits[0] = (png_byte)b;
     1214:                break;
     1215: 
     1216:             case 4: /* Replicate twice */
     1217:                /* Value is 1, 2, 3 or 4 */
     1218:                b = 0xf & ((0xf << 4) >> sig_bits[0]);
     1219:                b |= b << 4;
     1220:                sig_bits[0] = (png_byte)b;
     1221:                break;
     1222: 
     1223:             default:
     1224:                display_log(dp, LIBPNG_BUG, "invalid bit depth %d", bit_depth);
     1225:                break;
     1226:          }
     1227: 
     1228:          /* Convert bpp to bytes; this gives '1' for low-bit depth grayscale,
     1229:           * where there are multiple pixels per byte.
     1230:           */
     1231:          bpp = (bpp+7) >> 3;
     1232: 
     1233:          /* The mask can be combined with sig_bits[0] */
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libpng_upstream reproducer.c -L/tmp/libpng_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libpng_upstream
